SELECT * FROM LeaveRequests


        AND name = #{name}


        AND id_card = #{idCard}


        AND `type` = #{type}


        AND start_time = #{startTime}


order by `name`,`type`,`start_time` desc

SELECT * FROM Employeeattendancemonthly



        AND `name` = #{name}


        AND id_card = #{idCard}


        AND `status` = #{status}


        AND `year` = #{year}


        AND `month` = #{month}


order by `year`,`month`,`name`,`day` desc

select * from monthly_attendance


    AND `name` = #{name}


    AND `years` = #{years}


    AND `months` = #{months}


        AND `id_card` = #{idCard}


order by `name`,years,months

select * from employeeattendancemonthly where  id_card = #{idCard}
and `desc` like '%${flag}%'
and `year` = ${year}
and `month` = ${month}
   order by `day`

select * from employeeattendancemonthly where (`desc` like '%未签到%' or `desc` like '%无记录%')
and id_card = #{idCard}

and `year` = ${year}
and `month` = ${month}
order by `day`,`month`,`year`

select * from employeeattendancemonthly where (`desc` like '%未签离%' or `desc` like '%无记录%')
and id_card = #{idCard}

and `year` = ${year}
and `month` = ${month}
   order by `day`

select * from leaverequests where `years` = ${year}
and  `month`=${month}
and id_card = #{idCard}
and start_time >= #{errDay} and  start_time <= CONCAT(#{errDay}, ' 23:59:59')
and end_time >= #{errDay}

